### Step 3: Implement correction interpolation functions

`src/moshier/moon.rs` — add two private functions:
```rust
fn corr_mean_node(jd: f64) -> f64 {
    // Returns correction in degrees (see c-ref-mean-elements.md §2)
    if jd < JPL_DE431_START || jd > JPL_DE431_END { return 0.0; }
    let dj = jd - CORR_MNODE_JD_T0GREG;
    let dayscty = 36524.25;
    let i = (dj / dayscty).floor() as usize;
    let dfrac = (dj - i as f64 * dayscty) / dayscty;
    let table = &moon_tables::MEAN_NODE_CORR;
    table[i] + dfrac * (table[i + 1] - table[i])
}

fn corr_mean_apog(jd: f64) -> f64 {
    // Same logic, different table (see c-ref-mean-elements.md §3)
    if jd < JPL_DE431_START || jd > JPL_DE431_END { return 0.0; }
    let dj = jd - CORR_MNODE_JD_T0GREG;
    let dayscty = 36524.25;
    let i = (dj / dayscty).floor() as usize;
    let dfrac = (dj - i as f64 * dayscty) / dayscty;
    let table = &moon_tables::MEAN_APSIS_CORR;
    table[i] + dfrac * (table[i + 1] - table[i])
}
```

Note: Both use the same epoch constant `CORR_MNODE_JD_T0GREG` (the C source uses a separate `CORR_MAPOG_JD_T0GREG` but with the same value `-3063616.5`). One constant suffices.

### Step 4: Implement mean_node and mean_apogee

`src/moshier/moon.rs` — add two public functions:
```rust
pub fn mean_node(jd: f64) -> Result<[f64; 3], Error> {
    // See c-ref-mean-elements.md §4
    if jd < MOSHNDEPH_START || jd > MOSHNDEPH_END {
        return Err(Error::BeyondEphemerisLimits { jd_tt: jd, start: MOSHNDEPH_START, end: MOSHNDEPH_END });
    }
    let t = (jd - J2000) / 36525.0;
    let me = mean_elements(t);
    let dcor = corr_mean_node(jd) * 3600.0;  // degrees → arcseconds
    let lon = mod_2pi((me.swelp - me.nf - dcor) * STR);
    Ok([lon, 0.0, MOON_MEAN_DIST / AUNIT])
}

pub fn mean_apogee(jd: f64) -> Result<[f64; 3], Error> {
    // See c-ref-mean-elements.md §5
    if jd < MOSHNDEPH_START || jd > MOSHNDEPH_END {
        return Err(Error::BeyondEphemerisLimits { ... });
    }
    let t = (jd - J2000) / 36525.0;
    let me = mean_elements(t);
    // Step 1: raw apogee longitude (180° from perigee)
    let mut pol = [
        mod_2pi((me.swelp - me.mp) * STR + PI),
        0.0,
        MOON_MEAN_DIST * (1.0 + MOON_MEAN_ECC) / AUNIT,
    ];
    // Step 2: apply apogee correction
    let dcor = corr_mean_apog(jd) * DEGTORAD;
    pol[0] = mod_2pi(pol[0] - dcor);
    // Step 3: project onto ecliptic via mean orbital inclination
    let node = mod_2pi((me.swelp - me.nf) * STR - corr_mean_node(jd) * DEGTORAD);
    pol[0] = mod_2pi(pol[0] - node);  // argument relative to node
    let mut cart = polar_to_cartesian(pol);
    cart = cotrans(&cart, -MOON_MEAN_INCL * DEGTORAD);
    pol = cartesian_to_polar(cart);
    pol[0] = mod_2pi(pol[0] + node);  // ecliptic longitude
    Ok(pol)
}
```

Imports needed: `mod_2pi`, `polar_to_cartesian`, `cartesian_to_polar`, `cotrans` from `crate::math`.

### Step 5: Implement calc_mean_node and calc_mean_apogee in calc.rs

These wrap the raw computation with speed calculation and the pipeline. Key insight from `docs/c-ref-mean-elements.md` §7: `app_pos_etc_mean` converts ecliptic polar → ecliptic cartesian → equatorial cartesian, optionally precesses to J2000, then delegates to the existing `app_pos_rest()`. No separate pipeline function needed.

```rust
pub fn calc_mean_node(
    jd: f64,
    flags: CalcFlags,
    models: &AstroModels,
) -> Result<[f64; 24], Error> {
    let pos = moshier::moon::mean_node(jd)?;
    let pos_prev = moshier::moon::mean_node(jd - MEAN_NODE_SPEED_INTV)?;
    // Build ecliptic polar with speed (c-ref-mean-elements.md §6)
    let mut xx = [0.0; 6];
    xx[0] = pos[0]; xx[1] = pos[1]; xx[2] = pos[2];
    xx[3] = diff_radians(pos[0], pos_prev[0]) / MEAN_NODE_SPEED_INTV;
    xx[4] = 0.0; xx[5] = 0.0;

    // app_pos_etc_mean pipeline (c-ref-mean-elements.md §7):
    // 1. Ecliptic polar → ecliptic cartesian
    xx = polar_to_cartesian_with_speed(xx);
    // 2. Ecliptic → equatorial (rotate by -obliquity of date)
    let eps = if flags.contains(CalcFlags::J2000) {
        obliquity(J2000, flags, models)
    } else {
        obliquity(jd, flags, models)
    };
    let pos_eq = rotate_x_sincos([xx[0], xx[1], xx[2]], -eps.sin_eps, eps.cos_eps);
    let vel_eq = rotate_x_sincos([xx[3], xx[4], xx[5]], -eps.sin_eps, eps.cos_eps);
    xx = [pos_eq[0], pos_eq[1], pos_eq[2], vel_eq[0], vel_eq[1], vel_eq[2]];
    // 3. If J2000: precess equatorial back to J2000
    if flags.contains(CalcFlags::J2000) {
        let mut pos3 = [xx[0], xx[1], xx[2]];
        precess(&mut pos3, jd, flags, models, PrecessionDirection::DateToJ2000);
        xx[0] = pos3[0]; xx[1] = pos3[1]; xx[2] = pos3[2];
        if flags.contains(CalcFlags::SPEED) {
            precess_speed(&mut xx, jd, flags, models, PrecessionDirection::DateToJ2000);
        }
    }
    if !flags.contains(CalcFlags::SPEED) {
        xx[3] = 0.0; xx[4] = 0.0; xx[5] = 0.0;
    }
    // 4. Obliquity for app_pos_rest: J2000 obliquity if J2000 flag, date obliquity otherwise
    let nut_val = nutation(jd, flags, models);
    let nutv = if flags.contains(CalcFlags::SPEED) {
        Some(nutation(jd - NUT_SPEED_INTV, flags, models))
    } else { None };
    let mut xreturn = app_pos_rest(&mut xx, flags, &eps, &nut_val, nutv.as_ref());
    // Post-process: zero latitude/z for node (c-ref-mean-elements.md §6)
    if !flags.contains(CalcFlags::SIDEREAL) && !flags.contains(CalcFlags::J2000) {
        xreturn[1] = 0.0; xreturn[4] = 0.0; xreturn[5] = 0.0;
        xreturn[8] = 0.0; xreturn[11] = 0.0;
    }
    Ok(xreturn)
}

pub fn calc_mean_apogee(
    jd: f64,
    flags: CalcFlags,
    models: &AstroModels,
) -> Result<[f64; 24], Error> {
    // Same pipeline as mean_node but:
    // - Uses mean_apogee() instead of mean_node()
    // - Computes both lon AND lat speeds (apogee has non-zero lat from inclination)
    // - Post-process: only zero radial speed (xreturn[5] = 0.0)
    let pos = moshier::moon::mean_apogee(jd)?;
    let pos_prev = moshier::moon::mean_apogee(jd - MEAN_NODE_SPEED_INTV)?;
    let mut xx = [0.0; 6];
    xx[0] = pos[0]; xx[1] = pos[1]; xx[2] = pos[2];
    xx[3] = diff_radians(pos[0], pos_prev[0]) / MEAN_NODE_SPEED_INTV;
    xx[4] = diff_radians(pos[1], pos_prev[1]) / MEAN_NODE_SPEED_INTV;
    xx[5] = 0.0;
    // ... same pipeline as calc_mean_node ...
    let mut xreturn = app_pos_rest(...);
    xreturn[5] = 0.0;  // force radial speed = 0
    Ok(xreturn)
}
```

**Important**: The obliquity used for ecliptic→equatorial rotation is obliquity of DATE (not J2000), even when J2000 flag is set — because the input positions are in ecliptic of date. The J2000 obliquity is only used for app_pos_rest's ecliptic nutation step. Verify this against the ref doc §7 where `swi_coortrf2(xx, xx, -swed.oec.seps, swed.oec.ceps)` uses `swed.oec` (of date), and then J2000 sets `oe = &swed.oec2000` for the `app_pos_rest` call.

### Step 6: Implement ECL_NUT dispatch

`src/calc.rs`:
```rust
pub fn calc_ecl_nut(
    jd: f64,
    flags: CalcFlags,
    models: &AstroModels,
) -> [f64; 6] {
    // C ref: sweph.c:656-664, c-ref-calc.md §3 SE_ECL_NUT
    let eps = obliquity(jd, flags, models);
    let nut_val = nutation(jd, flags, models);
    [
        (eps.eps + nut_val.deps) * RADTODEG,  // true obliquity
        eps.eps * RADTODEG,                     // mean obliquity
        nut_val.dpsi * RADTODEG,               // nutation in longitude
        nut_val.deps * RADTODEG,               // nutation in obliquity
        0.0, 0.0,
    ]
}
```

### Step 7: Improve body dispatch in Ephemeris::calc()

`src/context.rs` — replace the current match (lines ~89-93) with explicit routing:
```rust
match body {
    Body::EclipticNutation => {
        let data = crate::calc::calc_ecl_nut(jd_tt, flags, models);
        return Ok(CalcResult { data, flags_used: flags });
    }
    Body::Earth => return Ok(CalcResult { data: [0.0; 6], flags_used: flags }),
    Body::MeanNode | Body::MeanApogee => {
        // Mean elements reject HELCTR/BARYCTR (c-ref-mean-elements.md §6)
        if flags.intersects(CalcFlags::HELCTR | CalcFlags::BARYCTR) {
            return Ok(CalcResult { data: [0.0; 6], flags_used: flags });
        }
    }
    _ => {}
}
// Existing eps_j2000 computation...
let xreturn = match body {
    Body::Sun => crate::calc::calc_sun(jd_tt, &eps_j2000, flags, models)?,
    Body::Moon => crate::calc::calc_moon(jd_tt, &eps_j2000, flags, models)?,
    Body::MeanNode => crate::calc::calc_mean_node(jd_tt, flags, models)?,
    Body::MeanApogee => crate::calc::calc_mean_apogee(jd_tt, flags, models)?,
    Body::Mercury | Body::Venus | Body::Mars | Body::Jupiter
    | Body::Saturn | Body::Uranus | Body::Neptune | Body::Pluto => {
        crate::calc::calc_planet(jd_tt, body, &eps_j2000, flags, models)?
    }
    _ => return Err(Error::EphemerisNotAvailable {
        body,
        source: crate::types::EphemerisSource::Moshier,
    }),
};
Ok(CalcResult { data: crate::calc::extract_output(&xreturn, flags), flags_used: flags })
```

Also remove the current blanket rejection of `HELCTR | BARYCTR` from the unsupported flags check (line 74). `plaus_iflag` already normalizes these to add NOABERR | NOGDEFL, and planets support heliocentric positions (they just skip corrections). Keep only `TOPOCTR | SIDEREAL` as rejected.

